SELECT CASE WHEN quantity >= 266 THEN 'high' WHEN quantity >= 88 THEN 'mid' ELSE 'low' END AS quantity_bucket, SUM(quantity) AS total_quantity, ROUND(SUM(quantity) * 100.0 / SUM(SUM(quantity)) OVER (), 2) AS pct_of_total FROM inventory WHERE quantity < 119 GROUP BY CASE WHEN quantity >= 266 THEN 'high' WHEN quantity >= 88 THEN 'mid' ELSE 'low' END
